1	/****************************************************************************
2	 * vendor/bes/chips/bes/bes_video_codec.c
3	 *
4	 * BES V4L2 M2M Codec Adaptation Layer (Skeleton).
5	 *
6	 * This file provides the V4L2 M2M codec_ops_s adaptation layer that
7	 * forwards video decode/encode requests to the BES hardware video
8	 * codec engine. All hardware-specific call sites are intentionally left
9	 * as TODO so the framework wiring can be reviewed before the actual
10	 * codec bring-up.
11	 *
12	 * Two independent device nodes are registered so that two video streams
13	 * can be decoded/encoded simultaneously.
14	 *
15	 * Reference:
16	 *   - nuttx/arch/sim/src/sim/sim_decoder.c  (reference decoder)
17	 *   - nuttx/arch/sim/src/sim/sim_encoder.c  (reference encoder)
18	 *   - vendor/bes/chips/bes/bes_audio_offload.c (audio offload pattern)
19	 *
20	 * See: docs/V4L2 M2M Codec 驱动开发指南.md
21	 ****************************************************************************/
