326	static void SetPpConfig_Jpeg_scaleratio0(struct JpegDecConfig *config, int w, int h, int ppflag)
327	{
328	  config->chroma_format = DEC_OUT_FRM_YUV420SP;
329	  config->ppu_config[0].enabled = 1;
330	  config->ppu_config[0].shaper_enabled = 1;
331	  config->ppu_config[0].chroma_format = PP_YUV420;
332	  config->ppu_config[0].out_p010 = 1;
333	  config->ppu_config[0].source_range = 1;
334	  config->ppu_config[0].dither_enable = 1;
335	  config->ppu_config[0].antialias = 1;
336	  config->ppu_config[0].crop_id = 1;
337	  config->ppu_config[0].align_pixel_w = 1;
338	  config->ppu_config[0].video_range = 1;
339	  config->ppu_config[0].antialias = 1;
340	  config->ppu_config[0].x_filter_param = 2;
341	  config->ppu_config[0].y_filter_param = 2;
342	  config->ppu_config[0].align = DEC_ALIGN_8B;
343	  if (ppflag)
344	  {
345	    if (w <= 1920 && h <= 1080)
346	    {
347	      config->ppu_config[0].pp_filter = BICUBIC;
348	      config->ppu_config[0].scale.width = w;
349	      config->ppu_config[0].scale.height = h;
350	      config->ppu_config[0].scale.enabled = 1;
351	    }
352	  }
353	}
