368	static bool bes_codec_dev_vpu_open() {
369	  vinfo("vpu open\n");
370		hal_cmu_vpu_set_mhz(200);
371	  hal_cmu_vpu_clock_enable();
372	  uint32_t *reg_data = (uint32_t *)(0x401e8000 + 0x800);
373	  vinfo("VPU_BASE_ID vpu reg data %x \n", *reg_data);
374		Platform_init();
375		memset(&_dwlinitparam, 0, sizeof(_dwlinitparam));
376		_dwlinitparam.client_type = DWL_CLIENT_TYPE_JPEG_DEC;
377		_dwl_inst = (void*)DWLInit(&_dwlinitparam);
378		// returnIfErrC(false, !_dwl_inst);
379	  if(!_dwl_inst){
380	    verr("DWLInit failed \n");
381	    return false;
382	  }
383		memset(&_stream_mem, 0, sizeof(struct DWLLinearMem));
384	  _stream_mem.mem_type = DWL_MEM_TYPE_DMA_HOST_TO_DEVICE | DWL_MEM_TYPE_CPU;
385		SET_MEM_USAGE(_stream_mem.mem_type, DWL_MEM_USAGE_IN_STRM, 0);
386		enum DWLRet dwl_ret = DWLMallocLinear(_dwl_inst, _max, &_stream_mem);
387		// returnIfErrC(false, dwl_ret);
388	  if(dwl_ret){
389	    verr("DWLMallocLinear failed dwl_ret %d\n", dwl_ret);
390	    return false;
391	  }
392		memset(&_dec_cfg, 0, sizeof(struct JpegDecConfig));
393		_dec_cfg.decoder_mode = DEC_NORMAL;
394	  _dec_cfg.error_ratio = 10;
395	  _dec_cfg.use_adaptive_buffers = 1;
396	  _dec_cfg.crc_enabled = 0;
397		enum DecRet ret = JpegDecInit(&_dec_inst, _dwl_inst, &_dec_cfg);
398		// returnIfErrC(false, ret);
399	  if(ret){
400	    verr("JpegDecInit failed ret %d\n", ret);
401	    return false;
402	  }
403		_framebuffer = (u8 *)kmm_memalign(64, _width * _height * 3 / 2);
404		// returnIfErrC(false, !_framebuffer);
405	  if(!_framebuffer){
406	    verr("_framebuffer malloc failed\n");
407	    return false;
408	  }
409		memset(&_mem, 0, sizeof(struct DWLLinearMem));
410	  _mem.mem_type = DWL_MEM_TYPE_DPB;
411	  SET_MEM_USAGE(_mem.mem_type, DWL_MEM_USAGE_OUT_PP, 0);
412		//JpegMallocSet(&_mem, _framebuffer);
413		_mem.logical_size = _width * _height * 3 / 2;
414		_mem.size = _width * _height * 3 / 2;;
415		_mem.virtual_address = (uint32_t *)_framebuffer;
416		_mem.bus_address = (uint32_t) _framebuffer;
417		ret = JpegDecAddBuffer(_dec_inst, &_mem);
418		if(ret!=0){
419	    verr("JpegDecAddBuffer failed ret %d\n", ret);
420	    return false;
421	  }
422		return true;
423	}
