425	bool bes_codec_dev_vpu_process(void* src_data, void* dst_data, uint32_t src_size, uint32_t* dst_size) {
426	  vinfo("vpu process start\n");
427		// uint32_t timebegain = hal_fast_sys_timer_get();
428		memcpy(_stream_mem.virtual_address, src_data, src_size);
429	
430		cache_flush(_stream_mem.virtual_address, ALIGN64(src_size));
431	
432		memset(&_jpeg_in, 0, sizeof(JpegDecInput));
433	  memset(&_image_info, 0, sizeof(JpegDecImageInfo));
434		_jpeg_in.stream_buffer = _stream_mem;
435	  _jpeg_in.stream_length = src_size;
436	  _jpeg_in.buffer_size = _max;
437	  _jpeg_in.stream = (u8 *)_stream_mem.virtual_address;
438	  _jpeg_in.thumbnail_done = 0;
439		enum DecRet ret = JpegDecGetImageInfo(_dec_inst, &_jpeg_in, &_image_info);
440	  if(ret){
441	    verr("JpegDecGetImageInfo failed ret %d\n", ret);
442	    return false;
443	  }
444		SetPpConfig_Jpeg_scaleratio0(&_dec_cfg, _width, _height, 1);
445		ret = JpegDecSetInfo(_dec_inst, &_dec_cfg); 
446	  if(ret){
447	    verr("JpegDecSetInfo failed ret %d\n", ret);
448	    return false;
449	  }
450		ret = JpegDecGetBufferInfo(_dec_inst, &_hbuf); 
451	  if(ret){
452	    verr("JpegDecGetBufferInfo failed ret %d\n", ret);
453	    return false;
454	  }
455		memset(&_jpeg_out, 0, sizeof(JpegDecOutput));
456		ret = JpegDecDecode(_dec_inst, &_jpeg_in, &_jpeg_out);
457		// uint32_t timeend = hal_fast_sys_timer_get();
458	  uint32_t luma_size   = _jpeg_out.pictures[0].output_width * _jpeg_out.pictures[0].output_height;
459	  uint32_t chroma_size = _jpeg_out.pictures[0].output_width * _jpeg_out.pictures[0].output_height / 2;
460	  u8 *luma_va   = (u8 *)_jpeg_out.pictures[0].output_picture_y.virtual_address;
461	  u8 *chroma_va = (u8 *)_jpeg_out.pictures[0].output_picture_cb_cr.virtual_address;
462		// vinfo("ret = %d,ifrm->index = %u \n",ret, ifrm->index);
463		vinfo("w = %u, h = %u \n", _jpeg_out.pictures[0].output_width, _jpeg_out.pictures[0].output_height);
464		switch (ret) {
465		case DEC_PIC_RDY: 
466			JpegDecPictureConsumed(_dec_inst, &_jpeg_out);
467			JpegDecNextPicture(_dec_inst, &_jpeg_out, &_image_info);
468			*dst_size = luma_size + chroma_size;
469			// dst_data = luma_va;
470	    memcpy(dst_data, luma_va, *dst_size);
471			// cache_invalid(ofrm->buff, ofrm->size);
472			break;
473		default:
474			*dst_size = 0;
475			verr("ret %d \n", ret);
476			break;
477		}
478		// timevpu += (timeend - timebegain);
479		// vinfo("[%u]osize %d ,frame = %u, vpu time:%u \n",ifrm->index, *dst_size, FAST_TICKS_TO_US(timeend - timebegain), FAST_TICKS_TO_US(timevpu));	
480	  vinfo("ret = %d, dst_size = %u \n",ret, *dst_size);
481		return true;
482	}
