484	/****************************************************************************
485	 * Name: bes_codec_process
486	 *
487	 * Description:
488	 *   Core processing routine — called from the work queue.  Fetches one
489	 *   buffer from the OUTPUT queue and one from the CAPTURE queue, then
490	 *   drives the hardware codec to produce a result.
491	 *
492	 *   For a decoder:
493	 *     - OUTPUT  = compressed bitstream (H.264 / H.265 / ...)
494	 *     - CAPTURE = decoded raw frame (YUV420 / NV12 / ...)
495	 *
496	 *   For an encoder:
497	 *     - OUTPUT  = raw frame (YUV420 / NV12 / ...)
498	 *     - CAPTURE = compressed bitstream
499	 *
500	 *   TODO: replace the skeleton body with actual BES hardware codec API
501	 *   calls (e.g. bes_vdec_decode_frame / bes_venc_encode_frame).
502	 *
503	 ****************************************************************************/
504	
505	static int bes_codec_process(FAR struct bes_codec_priv_s *priv,
506	                             FAR struct v4l2_buffer *dst_buf,
507	                             FAR struct v4l2_buffer *src_buf)
508	{
509	  struct v4l2_event event;
510	  uint8_t *src_data = NULL;
511	  uint32_t src_size = 0;
512	  int64_t src_pts   = 0;
513	  int64_t dst_pts   = 0;
514	  int ret;
515	
516	  if (src_buf != NULL){
517	    src_data = (uint8_t *)src_buf->m.vaddr;
518	    src_size = src_buf->bytesused;
519	    src_pts  = src_buf->timestamp.tv_sec * 1000000 + src_buf->timestamp.tv_usec;
520	  }else{
521	    priv->flushing = false;
522	    dst_buf->flags |= V4L2_BUF_FLAG_LAST;
523	    dst_buf->bytesused = 0;
524	    memset(&event, 0, sizeof(event));
525	    event.type = V4L2_EVENT_EOS;
526	    vinfo("event eos\n");
527	    codec_queue_event(priv->cookie, &event);
528	    codec_capture_put_buf(priv->cookie, dst_buf);
529	    return 0;
530	  }
531	  uint32_t isize = src_size;
532	  uint32_t osize = 0;
533	  void* idata = src_data;
534	  void* odata = src_buf->m.vaddr;
535	  vinfo("isize=%d osize=%d idata=%p odata=%p\n",isize, osize, idata, odata);
536	  bool dec_ret = bes_codec_dev_vpu_process(idata, odata, isize, &osize);
537	  if(dec_ret && osize){
538	    ret = 1;
539	  }else{
540	    ret = 0;
541	  }
542	
543	  // ret = 1;  /* placeholder: assume one output frame produced */
544	
545	  /* Return the consumed source buffer to the framework */
546	
547	  if (ret >= 0 && src_buf != NULL)
548	    {
549	      codec_output_put_buf(priv->cookie, src_buf);
550	    }
551	
552	  if (ret < 1)
553	    {
554	      return ret;
555	    }
556	
557	  dst_buf->bytesused = osize;
558	  /* TODO: dequeue the result from hardware and fill dst_buf.
559	   *
560	   * Decoder path:
561	   *   ret = bes_vdec_dequeue(priv->hw_handle, dst_buf->m.vaddr,
562	   *                          &dst_pts, &dst_buf->bytesused);
563	   *
564	   * Encoder path:
565	   *   ret = bes_venc_dequeue(priv->hw_handle, dst_buf->m.vaddr,
566	   *                          &dst_buf->bytesused, &dst_pts,
567	   *                          &dst_buf->flags);
568	   */
569	
570	  /* Handle flush completion */
571	
572	  dst_buf->timestamp.tv_usec = dst_pts % 1000000;
573	  dst_buf->timestamp.tv_sec  = dst_pts / 1000000;
574	
575	  codec_capture_put_buf(priv->cookie, dst_buf);
576	  return ret;
577	}
578	
579	/****************************************************************************
580	 * Name: bes_codec_work
581	 *
582	 * Description:
583	 *   Work queue callback.  Tries to dequeue one OUTPUT buffer and one
584	 *   CAPTURE buffer, processes them through the hardware codec, and
585	 *   re-arms itself if more data is available.
586	 *
587	 *   This follows the pattern recommended in the V4L2 M2M development
588	 *   guide: dequeue all processed buffers before queuing new ones.
589	 *
590	 ****************************************************************************/
591	
592	static void bes_codec_work(void *arg)
593	{
594	  FAR struct bes_codec_priv_s *priv = arg;
595	  FAR struct v4l2_buffer *src_buf;
596	  FAR struct v4l2_buffer *dst_buf;
597	  irqstate_t flags;
598	  int ret;
599	
600	  DEBUGASSERT(priv != NULL);
601	
602	  if (!priv->output_on && !priv->flushing){
603	    return;
604	  }
605	
606	  /* Try to get one compressed/raw input buffer from the OUTPUT queue */
607	
608	  src_buf = codec_output_get_buf(priv->cookie);
609	  if (src_buf == NULL && !priv->flushing)
610	    {
611	      return;
612	    }
613	
614	  /* Try to get one free output buffer from the CAPTURE queue */
615	
616	  dst_buf = codec_capture_get_buf(priv->cookie);
617	  if (dst_buf == NULL)
618	    {
619	      return;
620	    }
621	
622	  flags = irq_save_nopreempt();
623	  ret = bes_codec_process(priv, dst_buf, src_buf);
624	  irq_restore_nopreempt(flags);
625	
626	  /* If the hardware produced output, schedule another pass to drain
627	   * any remaining buffers.
628	   */
629	
630	  if (ret > 0)
631	    {
632	      work_queue(HPWORK, &priv->work, bes_codec_work, priv, 0);
633	    }
634	}
