813	/****************************************************************************
814	 * codec_ops_s — format enumeration / get / set / try
815	 *
816	 * The default codec type is decoder.  For a decoder:
817	 *   - OUTPUT  queue accepts compressed formats (H.264, H.265, ...)
818	 *   - CAPTURE queue produces raw formats (YUV420, NV12, ...)
819	 *
820	 * For an encoder the roles are reversed.
821	 ****************************************************************************/
822	
823	static int bes_codec_capture_enum_fmt(void *priv, struct v4l2_fmtdesc *fmt)
824	{
825	  FAR struct bes_codec_priv_s *ctx = priv;
826	  vinfo("%s %d type %d index %d\n", __func__, __LINE__, ctx->codec_type, fmt->index);
827	  /* Workaround: some callers (e.g. nxcodec) do not zero-initialize the
828	   * v4l2_fmtdesc struct before the first VIDIOC_ENUM_FMT call, leaving
829	   * index as stack garbage. If index is unreasonably large, treat it
830	   * as 0 so enumeration can start normally.
831	   */
832	
833	  if (fmt->index >= 16)
834	    {
835	      fmt->index = 0;
836	    }
837	
838	  /* Decoder: capture = raw pixel formats
839	   * Encoder: capture = compressed formats
840	   */
841	
842	  if (ctx->codec_type == BES_CODEC_DECODER)
843	    {
844	      switch (fmt->index)
845	        {
846	          case 0:
847	            fmt->pixelformat = V4L2_PIX_FMT_YUV420;
848	            break;
849	          case 1:
850	            fmt->pixelformat = V4L2_PIX_FMT_NV12;
851	            break;
852	          case 2:
853	            fmt->pixelformat = V4L2_PIX_FMT_NV12;
854	            break;
855	          default:
856	            return -EINVAL;
857	        }
858	    }
859	  else
860	    {
861	      switch (fmt->index)
862	        {
863	          case 0:
864	            fmt->pixelformat = V4L2_PIX_FMT_H264;
865	            break;
866	          case 1:
867	            fmt->pixelformat = V4L2_PIX_FMT_H265;
868	            break;
869	          case 2:
870	            fmt->pixelformat = V4L2_PIX_FMT_JPEG;
871	            break;
872	          default:
873	            return -EINVAL;
874	        }
875	    }
876	
877	  return OK;
878	}
879	
880	static int bes_codec_output_enum_fmt(void *priv, struct v4l2_fmtdesc *fmt)
881	{
882	  FAR struct bes_codec_priv_s *ctx = priv;
883	  vinfo("%s %d type %d index %d\n", __func__, __LINE__, ctx->codec_type, fmt->index);
884	  /* Workaround: some callers (e.g. nxcodec) do not zero-initialize the
885	   * v4l2_fmtdesc struct before the first VIDIOC_ENUM_FMT call, leaving
886	   * index as stack garbage. If index is unreasonably large, treat it
887	   * as 0 so enumeration can start normally.
888	   */
889	
890	  if (fmt->index >= 16)
891	    {
892	      fmt->index = 0;
893	    }
894	
895	  /* Decoder: output = compressed formats
896	   * Encoder: output = raw pixel formats
897	   */
898	
899	  if (ctx->codec_type == BES_CODEC_DECODER)
900	    {
901	      switch (fmt->index)
902	        {
903	          case 0:
904	            fmt->pixelformat = V4L2_PIX_FMT_H264;
905	            break;
906	          case 1:
907	            fmt->pixelformat = V4L2_PIX_FMT_H265;
908	            break;
909	          case 2:
910	            fmt->pixelformat = V4L2_PIX_FMT_JPEG;
911	            break;
912	          default:
913	            return -EINVAL;
914	        }
915	    }
916	  else
917	    {
918	      switch (fmt->index)
919	        {
920	          case 0:
921	            fmt->pixelformat = V4L2_PIX_FMT_YUV420;
922	            break;
923	          case 1:
924	            fmt->pixelformat = V4L2_PIX_FMT_NV12;
925	            break;
926	          default:
927	            return -EINVAL;
928	        }
929	    }
930	
931	  return OK;
932	}
