950	static int bes_codec_capture_s_fmt(void *priv, struct v4l2_format *fmt)
951	{
952	  FAR struct bes_codec_priv_s *ctx = priv;
953	  uint32_t width  = fmt->fmt.pix.width;
954	  uint32_t height = fmt->fmt.pix.height;
955	  uint32_t sizeimage;
956	
957	  /* Validate against max resolution */
958	
959	  if (width == 0 || height == 0 ||
960	      width > CONFIG_BES_VIDEO_CODEC_MAX_WIDTH ||
961	      height > CONFIG_BES_VIDEO_CODEC_MAX_HEIGHT)
962	    {
963	      verr("invalid resolution: %ux%u\n", width, height);
964	      return -EINVAL;
965	    }
966	
967	  ctx->capture_fmt = *fmt;
968	
969	  /* Calculate buffer size based on pixel format */
970	
971	  switch (fmt->fmt.pix.pixelformat)
972	    {
973	      case V4L2_PIX_FMT_YUV420:
974	      case V4L2_PIX_FMT_NV12:
975	        sizeimage = width * height * 3 / 2;
976	        ctx->capture_fmt.fmt.pix.sizeimage    = sizeimage;
977	        ctx->capture_fmt.fmt.pix.bytesperline = width;
978	        break;
979	
980	      case V4L2_PIX_FMT_H264:
981	      case V4L2_PIX_FMT_H265:
982	        /* Compressed: set to max I-frame size */
983	
984	        sizeimage = width * height;
985	        sizeimage = (sizeimage * 3 / 2) / 2 + 128;
986	        ctx->capture_fmt.fmt.pix.sizeimage = sizeimage;
987	        break;
988	
989	      default:
990	        return -EINVAL;
991	    }
992	
993	  ctx->capture_fmt.fmt.pix.field = V4L2_FIELD_NONE;
994	  return OK;
995	}
996	
997	static int bes_codec_output_s_fmt(void *priv, struct v4l2_format *fmt)
998	{
999	  FAR struct bes_codec_priv_s *ctx = priv;
1000	  uint32_t width  = fmt->fmt.pix.width;
1001	  uint32_t height = fmt->fmt.pix.height;
1002	  uint32_t sizeimage;
1003	
1004	  if (width == 0 || height == 0 ||
1005	      width > CONFIG_BES_VIDEO_CODEC_MAX_WIDTH ||
1006	      height > CONFIG_BES_VIDEO_CODEC_MAX_HEIGHT)
1007	    {
1008	      verr("invalid resolution: %ux%u\n", width, height);
1009	      return -EINVAL;
1010	    }
1011	
1012	  ctx->output_fmt = *fmt;
1013	
1014	  switch (fmt->fmt.pix.pixelformat)
1015	    {
1016	      case V4L2_PIX_FMT_H264:
1017	      case V4L2_PIX_FMT_H265:
1018	      case V4L2_PIX_FMT_JPEG:
1019	        /* Compressed input: set to a safe upper bound (half of raw) */
1020	
1021	        sizeimage = width * height * 3 / 4;
1022	        if (sizeimage < CONFIG_BES_VIDEO_CODEC_COMPRESSED_BUF_SIZE)
1023	          {
1024	            sizeimage = CONFIG_BES_VIDEO_CODEC_COMPRESSED_BUF_SIZE;
1025	          }
1026	        ctx->output_fmt.fmt.pix.sizeimage = sizeimage;
1027	        break;
1028	      case V4L2_PIX_FMT_YUV420:
1029	      case V4L2_PIX_FMT_NV12:
1030	        sizeimage = width * height * 3 / 2;
1031	        ctx->output_fmt.fmt.pix.sizeimage    = sizeimage;
1032	        ctx->output_fmt.fmt.pix.bytesperline = width;
1033	        break;
1034	
1035	      default:
1036	        return -EINVAL;
1037	    }
1038	
1039	  ctx->output_fmt.fmt.pix.field = V4L2_FIELD_NONE;
1040	  return OK;
1041	}
