1382	/****************************************************************************
1383	 * Name: bes_video_codec_initialize
1384	 *
1385	 * Description:
1386	 *   Register two V4L2 M2M Codec device nodes that route their data path
1387	 *   through the BES hardware video codec engine.
1388	 *
1389	 *     - Instance 0: /dev/video0  (CONFIG_BES_VIDEO_CODEC_DEV_PATH0)
1390	 *     - Instance 1: /dev/video1  (CONFIG_BES_VIDEO_CODEC_DEV_PATH1)
1391	 *
1392	 *   Two independent nodes are registered so that two video streams can
1393	 *   be decoded (or encoded) simultaneously without contention.
1394	 *
1395	 *   Each open() on a device node creates a fresh per-session context
1396	 *   (bes_codec_priv_s), so the two streams are fully isolated.
1397	 *
1398	 * Returned Value:
1399	 *   OK on success; a negated errno on failure.
1400	 *
1401	 ****************************************************************************/
1402	
1403	int bes_video_codec_initialize(void)
1404	{
1405	  static bool initialized = false;
1406	  int i;
1407	  int ret;
1408	
1409	  if (initialized)
1410	    {
1411	      return OK;
1412	    }
1413	
1414	  for (i = 0; i < BES_CODEC_INSTANCE_NUM; i++)
1415	    {
1416	      FAR struct bes_codec_dev_s *dev = &g_bes_codec_devs[i];
1417	
1418	      vinfo("registering %s (instance %d)\n", dev->devpath, dev->instance_id);
1419	
1420	      ret = codec_register(dev->devpath, &dev->codec);
1421	      if (ret < 0)
1422	        {
1423	          verr("ERROR: codec_register(%s) failed: %d\n",
1424	               dev->devpath, ret);
1425	
1426	          /* Unregister any previously registered nodes */
1427	
1428	          while (i > 0)
1429	            {
1430	              i--;
1431	              codec_unregister(g_bes_codec_devs[i].devpath);
1432	            }
1433	
1434	          return ret;
1435	        }
1436	    }
1437	
1438	  initialized = true;
1439	  vinfo("registered %d codec device nodes: %s, %s\n",
1440	        BES_CODEC_INSTANCE_NUM,
1441	        g_bes_codec_devs[0].devpath,
1442	        g_bes_codec_devs[1].devpath);
1443	  return OK;
1444	}
