1269	static int codec_mmap(FAR struct file *filep,
1270	                      FAR struct mm_map_entry_s *map)
1271	{
1272	  FAR struct inode *inode = filep->f_inode;
1273	  FAR codec_mng_t *cmng = inode->i_private;
1274	  FAR codec_file_t *cfile = filep->f_priv;
1275	  FAR codec_type_inf_t *type_inf;
1276	  int ret = -EINVAL;
1277	  size_t total_size;
1278	  size_t buf_size;
1279	
1280	  if (map == NULL)
1281	    {
1282	      return -EINVAL;
1283	    }
1284	
1285	  if (map->offset < CAPTURE_BUF_OFFSET)
1286	    {
1287	      type_inf = &cfile->output_inf;
1288	      buf_size = CODEC_OUTPUT_G_BUFSIZE(cmng->codec, cfile->priv);
1289	    }
1290	  else
1291	    {
1292	      type_inf     = &cfile->capture_inf;
1293	      map->offset -= CAPTURE_BUF_OFFSET;
1294	      buf_size     = CODEC_CAPTURE_G_BUFSIZE(cmng->codec, cfile->priv);
1295	    }
1296	
1297	  if (buf_size == 0)
1298	    {
1299	      return -EINVAL;
1300	    }
1301	
1302	  total_size = type_inf->bufinf.container_size * buf_size;
1303	  if (map->offset >= 0 && map->offset < total_size &&
1304	      map->length && map->offset + map->length <= total_size)
1305	    {
1306	      map->vaddr  = type_inf->bufheap + map->offset;
1307	      map->munmap = codec_munmap;
1308	      ret = mm_map_add(get_current_mm(), map);
1309	    }
1310	
1311	  return ret;

