386	                                    reqbufs->memory);
387	      if (ret < 0)
388	        {
389	          return ret;
390	        }
391	
392	      buf_size = CODEC_OUTPUT_G_BUFSIZE(cmng->codec, cfile->priv);
393	      buf_cnt = CODEC_OUTPUT_G_BUFCNT(cmng->codec, cfile->priv);
394	      reqbufs->count = MIN(buf_cnt, reqbufs->count);
395	    }
396	  else
397	    {
398	      ret = CODEC_CAPTURE_TRY_MEMORY(cmng->codec, cfile->priv,
399	                                     reqbufs->memory);
400	      if (ret < 0)
401	        {
402	          return ret;
403	        }
404	
405	      buf_size = CODEC_CAPTURE_G_BUFSIZE(cmng->codec, cfile->priv);
406	      buf_cnt = CODEC_CAPTURE_G_BUFCNT(cmng->codec, cfile->priv);
407	      reqbufs->count = MIN(buf_cnt, reqbufs->count);
408	    }
409	
410	  if (buf_size == 0)
411	    {
412	      return -EINVAL;
413	    }
414	
415	  type_inf = codec_get_type_inf(cfile, reqbufs->type);
416	  video_framebuff_change_mode(&type_inf->bufinf, reqbufs->mode);
417	  ret = video_framebuff_realloc_container(&type_inf->bufinf,
418	                                          reqbufs->count);
419	
420	#ifdef CONFIG_DMA_SHARED_BUFFER
421	  if (ret == 0 && reqbufs->memory == V4L2_MEMORY_DMABUF)
422	    {
423	      /* DMABUF mode: only allocate containers, no bufheap needed.
424	       * Free existing bufheap if present.
425	       */
426	
427	      if (type_inf->bufheap != NULL)
428	        {
429	          if (cmng->codec->ops->free_buf)
430	            {
431	              cmng->codec->ops->free_buf(cfile->priv, type_inf->bufheap);
432	            }
433	          else
434	            {
435	              kumm_free(type_inf->bufheap);
436	            }
437	
438	          type_inf->bufheap = NULL;
439	        }
440	    }
441	  else
442	#endif
443	  if (ret == 0 && reqbufs->memory == V4L2_MEMORY_MMAP)
444	    {
445	      if (cmng->codec->ops->free_buf)
446	        {
447	          cmng->codec->ops->free_buf(cfile->priv, type_inf->bufheap);
448	        }
449	      else
450	        {
451	          kumm_free(type_inf->bufheap);
452	        }
453	
454	      type_inf->bufheap = cmng->codec->ops->alloc_buf ?
455	        cmng->codec->ops->alloc_buf(cfile->priv, reqbufs->count * buf_size) :
456	        kumm_memalign(32, reqbufs->count * buf_size);
457	      if (type_inf->bufheap == NULL)
458	        {
459	          ret = -ENOMEM;
460	        }
461	    }
462	
463	  return ret;
464	}
